package com.jobmatcher.controller;import com.jobmatcher.dto.ProfileRequest;import com.jobmatcher.dto.AuthDtos.UserView;import com.jobmatcher.model.User;import com.jobmatcher.repository.UserRepository;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/profile") public class ProfileController {private final UserRepository repo;public ProfileController(UserRepository r){repo=r;}private Long id(java.security.Principal p){return Long.valueOf(p.getName());}private User get(java.security.Principal p){return repo.findById(id(p)).orElseThrow();}@GetMapping public UserView getProfile(java.security.Principal p){User u=get(p);return new UserView(u.getId(),u.getName(),u.getEmail(),u.getQualification(),u.getExperience(),u.getSkills());}@PutMapping public UserView update(@Valid @RequestBody ProfileRequest r,java.security.Principal p){User u=get(p);if(!u.getEmail().equalsIgnoreCase(r.email())&&repo.existsByEmail(r.email()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");u.setName(r.name());u.setEmail(r.email());u.setQualification(r.qualification());u.setExperience(r.experience());u.setSkills(r.skills());repo.save(u);return new UserView(u.getId(),u.getName(),u.getEmail(),u.getQualification(),u.getExperience(),u.getSkills());}}
